"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[102],{9102:(e,t,i)=>{i.r(t),i.d(t,{PAPERS:()=>a});let a=[{id:"2610.18829",title:"OmniCompass: A Holistic Benchmark for Omni-Modal Video Grounding and Understanding",up:200,href:"https://arxiv.org/abs/2610.18829",abstract:"With the rapid development of multimodal large language models (MLLMs), evaluating their video understanding capabilities has become increasingly important. Existing video understanding benchmarks cover only part of the evaluation dimensions, limiting systematic diagnosis of omni-modal video understanding. We introduce OmniCompass, a holistic benchmark for omni-modal video grounding and understanding. OmniCompass defines two evaluation tracks: OmniCompass-VL assesses vision-language models on tasks requiring visual evidence, while OmniCompass-AV assesses omni-modal models on tasks requiring jo",pdfUrl:"https://arxiv.org/pdf/2610.18829",primaryCategory:"cs.CV",published:"2026-10-13T00:00:00Z"},{id:"2610.21601",title:"Waypoint-OPD: Transferring RL-Induced Policy Shifts via Gated On-Policy Distillation",up:123,href:"https://arxiv.org/abs/2610.21601",abstract:"Policy-shift distillation reuses the difference between a teacher's log probabilities before and after reinforcement learning (RL) as supervision on student-generated trajectories. However, this endpoint policy shift cannot reveal whether local action preferences evolved consistently during teacher training. The same endpoint shift can result from early and late shifts that reinforce or partially cancel each other. We investigate whether agreement between early and late teacher policy shifts can guide selective transfer. We introduce Waypoint-guided On-Policy Distillation (Waypoint-OPD), which",pdfUrl:"https://arxiv.org/pdf/2610.21601",primaryCategory:"cs.LG",published:"2026-10-15T00:00:00Z"},{id:"2610.18813",title:"Self-Evolving Agent Harness",up:72,href:"https://arxiv.org/abs/2610.18813",abstract:"Harness self-evolution revises an agent's software scaffolding, including prompts, memory, workflows, and executable components, while keeping model weights fixed. We formalize a feedback-driven process in which accepted revisions persist across runs. The framework separates update targets from proposal and admission mechanisms. It distinguishes changes to interpreted state from revisions to tools and code, repository-level control logic, and plugin composition. We characterize search through evolutionary optimization and examine its reliability through continual PAC-learning. Under explicit a",pdfUrl:"https://arxiv.org/pdf/2610.18813",primaryCategory:"cs.AI",published:"2026-10-13T00:00:00Z"},{id:"2610.22347",title:"Speculative Forcing for Efficient Autoregressive Video Generation",up:58,href:"https://arxiv.org/abs/2610.22347",abstract:"Few-step autoregressive video generators enable streaming generation, yet they run every token through the final denoising step, regardless of how much refinement it needs. We find this uniform computation is often unnecessary: many tokens already closely match their eventual full-step outputs in the initial steps, while others require refinement until the end. We introduce Speculative Forcing, a framework that treats intermediate clean estimates as drafts and predicts when individual tokens can be safely accepted early. Once accepted, a token is frozen as its final output and undergoes no fur",pdfUrl:"https://arxiv.org/pdf/2610.22347",primaryCategory:"cs.CV",published:"2026-10-15T00:00:00Z"},{id:"2610.14993",title:"Learning Where to Split: Dynamic Band Splitting for Audio Source Separation",up:49,href:"https://arxiv.org/abs/2610.14993",abstract:"Audio source separation models must preserve fine spectral structure while keeping the cost of the separator tractable. Band-split architectures reduce this cost by manually partitioning the spectrum into predefined frequency bands and encoding each band as a token, but the same boundaries are used for every mixture. Because informative spectral structure varies with source content, fixed boundaries can merge discriminative components or spend tokens where little resolution is needed. We introduce Dynamic Band Splitting (DBS), an end-to-end framework that adapts boundary locations and band wid",pdfUrl:"https://arxiv.org/pdf/2610.14993",primaryCategory:"cs.SD",published:"2026-10-10T00:00:00Z"},{id:"2610.22264",title:"SCOPE: Semantic Bounded Credit Optimization for Prompt Engineering in Text-to-image Generation",up:45,href:"https://arxiv.org/abs/2610.22264",abstract:"Reinforcement learning (RL) enables language models to improve text-to-image (T2I) generation by rewriting prompts for a frozen image generator. Existing methods typically apply a single signal derived from the image to individual subword tokens, although objects, counts, attributes, and relations form coherent semantic spans. We propose SCOPE, an objective based on Group Relative Policy Optimization (GRPO) that aligns update weighting with this structure. The rewriter jointly generates an enhanced prompt and its semantic partition. SCOPE pools shifts in policy log probabilities within each sp",pdfUrl:"https://arxiv.org/pdf/2610.22264",primaryCategory:"cs.CV",published:"2026-10-15T00:00:00Z"},{id:"2610.22341",title:"3DCodeVerse: Exploring 3D Worlds as Code",up:42,href:"https://arxiv.org/abs/2610.22341",abstract:"We introduce 3DCodeVerse, a research ecosystem that enables coding agents to create editable and verifiable 3D content at scale. 3DCodeVerse comprises large-scale, high-quality datasets of executable 3D code, a coding harness for spatial reasoning and automated verification, and practical guidance for 3D coding. First, we construct 3DCodeVerse-2M, a large-scale curated dataset of standalone 3D executable code. We build this corpus by collecting open-source data, converting specialized representations, and generating new programs with coding agents. Each program is packaged with the source file",pdfUrl:"https://arxiv.org/pdf/2610.22341",primaryCategory:"cs.CV",published:"2026-10-15T00:00:00Z"},{id:"2610.17665",title:"RoTA-Bench: Evaluating 3D Spatial Reasoning through Interactive Projection Alignment",up:31,href:"https://arxiv.org/abs/2610.17665",abstract:"Can vision-language models turn 2D observations into 3D understanding that supports precise action? This requires inferring object geometry, anticipating the effects of rotation, and refining actions through visual feedback. We introduce RoTA-Bench to evaluate these abilities through interactive 3D-to-2D projection alignment. Given a target silhouette, a model observes a rotated object and chooses successive rotations to recover the target projection within a limited action budget. Our automated pipeline constructs silhouette-preserving 3D objects from 2D icons and uses reversible initializati",pdfUrl:"https://arxiv.org/pdf/2610.17665",primaryCategory:"cs.AI",published:"2026-10-14T00:00:00Z"},{id:"2610.19849",title:"DeltaStreamer: Towards Human-Like Agentic Streaming Video Understanding",up:30,href:"https://arxiv.org/abs/2610.19849",abstract:"We propose DeltaStreamer, a novel agentic framework for streaming video understanding inspired by how humans observe, remember, and investigate. Streaming video understanding requires a system to retain evidence before knowing which details future queries will need. Existing approaches often obscure event transitions and omit relevant details when compressing video history, and cannot recover missing visual evidence. DeltaStreamer addresses these limitations by combining change-aware memory with query-driven planning and targeted evidence gathering with replay. Before a query arrives, it conti",pdfUrl:"https://arxiv.org/pdf/2610.19849",primaryCategory:"cs.CV",published:"2026-10-14T00:00:00Z"},{id:"2610.20341",title:"InfiniSplat v2: Analyzing and Improving Feed-Forward 3DGS from Any Views",up:29,href:"https://arxiv.org/abs/2610.20341",abstract:"Feed-forward Gaussian reconstruction builds 3D scenes directly from input images for novel view rendering, but learning Gaussian attributes from predicted geometry for high-quality rendering under large viewpoint changes remains challenging. We analyze limitations in Gaussian attribute learning and introduce InfiniSplat v2, which improves rendering quality through architectural and training changes. Our method decouples geometry and attribute prediction with a frozen geometry branch, aligns predicted Gaussians using ground-truth camera poses during training, and adopts large-angle target view ",pdfUrl:"https://arxiv.org/pdf/2610.20341",primaryCategory:"cs.CV",published:"2026-10-14T00:00:00Z"},{id:"2610.20693",title:"Orbia: Do Generated Videos Form a Consistent 3D World?",up:28,href:"https://arxiv.org/abs/2610.20693",abstract:"Video generators serve as interactive worlds for exploration and simulation, yet realistic and visually appealing frames do not necessarily depict a consistent 3D world. Existing benchmarks assess selected geometric properties or use vision-language models to judge memory and consistency, leaving systematic 3D evaluation underexplored. We introduce Orbia, the first benchmark dedicated to a systematic and comprehensive evaluation of 3D consistency in interactive world models. Through controlled exploration and revisit, we organize the evaluation into three dimensions: input preservation, genera",pdfUrl:"https://arxiv.org/pdf/2610.20693",primaryCategory:"cs.CV",published:"2026-10-14T00:00:00Z"},{id:"2610.22174",title:"Mosaic: Multi-Session Agentic Reinforcement Learning",up:26,href:"https://arxiv.org/abs/2610.22174",abstract:"Most existing agentic reinforcement learning methods assume single-session trajectories, where interaction proceeds within one continuously accumulated context. However, agentic techniques such as context compaction and subagent forking may produce trajectories spanning multiple sessions, creating a mismatch between the single-session training assumption and inference-time execution. Therefore, we introduce Multi-Session Agentic Reinforcement Learning, a more general setting that supports an arbitrary number of sessions within a trajectory. Under this setting, a widely adopted method is to bro",pdfUrl:"https://arxiv.org/pdf/2610.22174",primaryCategory:"cs.CL",published:"2026-10-15T00:00:00Z"},{id:"2610.21306",title:"VLA-Δ: Learning Physical State Transition for Vision-Language-Action Models",up:24,href:"https://arxiv.org/abs/2610.21306",abstract:"Vision-language-action (VLA) models transfer semantic knowledge acquired through vision-language pretraining to robot control, achieving strong performance across various benchmarks. However, most VLAs directly map observations to demonstrated actions without explicit supervision of intermediate physical state changes, making them prone to overfitting observation-action correspondences. Some methods introduce intermediate reasoning or future-state prediction in language, visual, or latent spaces to guide action generation, but do not explicitly supervise the physical state transition itself. W",pdfUrl:"https://arxiv.org/pdf/2610.21306",primaryCategory:"cs.CV",published:"2026-10-15T00:00:00Z"},{id:"2610.22194",title:"AutoSFT: An Agentic System for Automated Data Research in Supervised Fine-Tuning",up:22,href:"https://arxiv.org/abs/2610.22194",abstract:"Language model agents increasingly automate post-training, but when given the full training stack they converge on supervised fine-tuning and spend most effort revising training data. Existing systems give the agent one kind of control, selecting rows from a fixed pool or calling a generator, whereas a human data engineer adjusts proportions, prunes, repairs, replaces and synthesizes the data. We design a data action space for these changes and ask whether an automated system can make the full range rather than one of them, and what structure that requires. We first run this loop with a single",pdfUrl:"https://arxiv.org/pdf/2610.22194",primaryCategory:"cs.AI",published:"2026-10-15T00:00:00Z"},{id:"2610.22344",title:"MLExpert: Towards a Generalist Agentic Model for Autonomous Machine Learning Engineering",up:21,href:"https://arxiv.org/abs/2610.22344",abstract:"Large language models (LLMs) are expanding from assisting scientific research and engineering to autonomously developing and improving AI systems, advancing AI for AI (AI4AI) as a pathway toward recursive self-improvement (RSI). Workflow-driven machine learning engineering (MLE) systems provide a practical path toward this pursuit through complex orchestration that manages long-horizon experimentation, while recent MLE systems adopt model-directed interaction, allowing models to autonomously organize experiments and adapt optimization strategies based on execution feedback. However, feedback f",pdfUrl:"https://arxiv.org/pdf/2610.22344",primaryCategory:"cs.AI",published:"2026-10-15T00:00:00Z"},{id:"2610.16784",title:"InfoVis: Unified Slide Image Generation and Editing",up:20,href:"https://arxiv.org/abs/2610.16784",abstract:"Generating and editing presentation slides requires models to combine accurate text rendering, instruction following, visual grounding, aesthetic design, and precise editing within one canvas. Existing work covers only subsets of these capabilities and lacks large-scale slide-native supervision and diagnostic evaluation. We formulate four slide-centric tasks and build a scalable data engine with over 13M continual-pretraining records and 1.9M supervised fine-tuning records. We also introduce VisSlideBench, a benchmark of 1,527 manually screened instances that covers all four tasks with task-sp",pdfUrl:"https://arxiv.org/pdf/2610.16784",primaryCategory:"cs.CV",published:"2026-10-12T00:00:00Z"},{id:"2610.20731",title:"WorldCast: Exploring Intelligent Visual Generation in World State Prediction",up:20,href:"https://arxiv.org/abs/2610.20731",abstract:"Humans interpret multimodal observations of the world and forecast how it will evolve. Recent multimodal generative systems have demonstrated similar capabilities: they can integrate multimodal context and synthesize visual outputs that depict changes in the world. To characterize this emerging trajectory, we organize model capabilities into a four-level hierarchy and discover that higher-level tasks remain relatively underexplored despite model progress. To bridge this gap, we explore model performance on multi-step world state prediction, a high-level task that requires models to forecast su",pdfUrl:"https://arxiv.org/pdf/2610.20731",primaryCategory:"cs.CV",published:"2026-10-14T00:00:00Z"},{id:"2610.17560",title:"EdgeWise: Bringing Long-Horizon Agents to the Edge via Selective Cloud Delegation",up:19,href:"https://arxiv.org/abs/2610.17560",abstract:"Complex and long-horizon agent tasks often rely on frontier models deployed in the cloud to achieve strong performance. However, using these models for every step of a long-horizon trajectory incurs substantial inference cost, even though not all steps may require the same level of model capability. In this paper, we find that allocating the LLM to only a small subset of key steps can achieve performance comparable to full LLM execution while significantly reducing inference cost. Motivated by this observation, we propose EdgeWise, an edge-cloud collaboration framework that deploys an SLM on t",pdfUrl:"https://arxiv.org/pdf/2610.17560",primaryCategory:"cs.CL",published:"2026-10-13T00:00:00Z"},{id:"2610.20603",title:"CommerceGen-Studio: An End-to-End Framework for Commercial-Grade Main-Image Generation",up:18,href:"https://arxiv.org/abs/2610.20603",abstract:"We present CommerceGen-Studio, an end-to-end framework for generating commercial-grade main images for e-commerce Stock Keeping Units (SKUs). Our framework is organized along a three-stage pipeline of information extraction, semantic rewriting, and multi-condition generation: Prompt-Eval-Refine-Loop Agent (PERL-Agent) distills heterogeneous SKU metadata into concise selling-point text lists through an iterative closed loop of VLM and LLM roles scored by a reference-free rubric. Layout Thinker Optimization (LTO) aligns the rewriter with both caption and rendered-image quality via alternating do",pdfUrl:"https://arxiv.org/pdf/2610.20603",primaryCategory:"cs.CV",published:"2026-10-14T00:00:00Z"},{id:"2610.22282",title:"Routing Policy Optimization for Online Diffusion Reinforcement Learning",up:18,href:"https://arxiv.org/abs/2610.22282",abstract:"Reinforcement learning can align visual generators with reward signals beyond their pretraining objectives, but existing score-function methods typically introduce stochasticity by perturbing the reverse denoising trajectory, leading to costly rollout-based optimization. We instead ask whether stochastic exploration can be introduced inside the generator while preserving its original sampler. Routing Policy Optimization (RPO) answers this question by turning attention routing into a stochastic exploration action. At a few selected denoising levels, each query block keeps its own block and samp",pdfUrl:"https://arxiv.org/pdf/2610.22282",primaryCategory:"cs.CV",published:"2026-10-15T00:00:00Z"},{id:"2610.22131",title:"Intern-Decision: Efficient Multimodal Decision Making with Autoregressive Masked Language Modeling",up:16,href:"https://arxiv.org/abs/2610.22131",abstract:"Interactive agents repeatedly choose among a finite set of actions, labels, or ordinal outcomes. Generating a free-form response for each choice adds latency and complicates the interface between a model and its environment. We present Intern-Decision, a family of 0.8B, 2B, and 4B multimodal decision models that return structured choices and candidate probabilities from text and optional images. Our autoregressive masked language modeling objective places one decision placeholder per field in a complete assistant JSON skeleton. Ground-truth symbols appear only in supervision, while all fields ",pdfUrl:"https://arxiv.org/pdf/2610.22131",primaryCategory:"cs.CL",published:"2026-10-15T00:00:00Z"},{id:"2610.22192",title:"Terminal-RSI: Recursive Self-Improving Terminal Agents via Recursive Self-Rewrite and Policy-Refine",up:16,href:"https://arxiv.org/abs/2610.22192",abstract:"Converting verifier outcomes into useful policy updates and partial progress into complete task resolution is crucial for terminal agents. We present Terminal-RSI, which alternates Recursive Self-Rewrite (RSR) of verified trajectories with critic-inheriting Recursive Policy-Refine (RPR). We formulate Turn-Boundary Skip-Observation GAE (TB-GAE) to retain token-specific baselines while applying decay across interaction turns. Family Dense Reward (FDR) calibrates semantic progress across task families; Success-Prioritized Reward (SPR) separates strict success from bounded partial credit. A Warm-u",pdfUrl:"https://arxiv.org/pdf/2610.22192",primaryCategory:"cs.AI",published:"2026-10-15T00:00:00Z"},{id:"2610.09695",title:"Do Better Visual Representations Always Lead to Better End-to-End Autonomous Driving?",up:13,href:"https://arxiv.org/abs/2610.09695",abstract:"Visual foundation models (VFMs) are increasingly integrated into end-to-end autonomous driving for their powerful representations, yet it remains unclear when these representations improve driving performance. To investigate this question, we introduce ViRA, a planner-agnostic visual representation alignment framework that keeps the planner architecture and inference cost unchanged. Our study reveals three findings: (1) VFM-guided visual representations consistently improve driving performance across diverse end-to-end planners, with gains extending to zero-shot closed-loop evaluation. (2) The",pdfUrl:"https://arxiv.org/pdf/2610.09695",primaryCategory:"cs.RO",published:"2026-10-07T00:00:00Z"},{id:"2610.13781",title:"SimVTA: Simulation-Grounded Video-Trajectory Alignment for Driving World Action Models",up:13,href:"https://arxiv.org/abs/2610.13781",abstract:"Driving world action models (WAMs) learn from paired trajectories and future observations. Post-training with reinforcement learning allows the policy to explore alternative trajectories and improve planning using driving rewards. However, driving logs contain future videos only for the recorded trajectories, leaving these alternatives without corresponding visual supervision. Thus, we introduce SimVTA, a simulation-grounded post-training framework that combines trajectory optimization with video supervision. First, we sample candidate trajectories for each observation and use a real-world sim",pdfUrl:"https://arxiv.org/pdf/2610.13781",primaryCategory:"cs.CV",published:"2026-10-09T00:00:00Z"},{id:"W7171617880",title:"Machine-Speed Intrusion: A Detection Engineering Analysis of the July 2026 Hugging Face Agent Campaign",up:0,href:"https://doi.org/10.5281/zenodo.21686546",doi:"https://doi.org/10.5281/zenodo.21686546",year:2026,openalexId:"https://openalex.org/W7171617880"},{id:"W7171936549",title:"Could a Capability-Security Architecture Have Contained the July 2026 OpenAI-Hugging Face Agentic Exploit Chain?",up:0,href:"https://doi.org/10.5281/zenodo.21715175",doi:"https://doi.org/10.5281/zenodo.21715175",year:2026,openalexId:"https://openalex.org/W7171936549"},{id:"W7203931864",title:"hf-data-agent: a Hugging Face backed RAG data agent",up:0,href:"https://doi.org/10.5281/zenodo.22043399",doi:"https://doi.org/10.5281/zenodo.22043399",year:2026,openalexId:"https://openalex.org/W7203931864"}]}}]);